# identify 2x2 zero squares where 8-neighbor outer border all 9 (exclude seed cells)
candidates=[]
for i in range(27-1):
 for j in range(20-1):
  if all(g[x][y]==0 for x,y in [(i,j),(i+1,j),(i,j+1),(i+1,j+1)]):
   border=[g[x][y] for x in range(max(0,i-1),min(27,i+3)) for y in range(max(0,j-1),min(20,j+3)) if not(i<=x<=i+1 and j<=y<=j+1)]
   if all(v==9 for v in border): candidates.append((i,j))
print(candidates)
